      },
      "verification": {
        "what": "failover functionality",
        "how": "simulate replica failure",
        "expected": "traffic rerouted to primary without issues"
      },
      "preconditions": [
        {
          "description": "replicas must be online",
          "fact": "replicas_online",
          "established_by": "provision_replicas"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "provision_replicas",
      "to_task": "configure_pgbouncer",
      "kind": "hard"
    },
    {
      "from_task": "provision_replicas",
      "to_task": "verify_replica_lag",
      "kind": "hard"
    },
    {
      "from_task": "verify_replica_lag",
      "to_task": "drain_traffic",
      "kind": "hard"
    },
    {
      "from_task": "drain_traffic",
      "to_task": "monitor_stale_reads",
      "kind": "hard"
    },
    {
      "from_task": "provision_replicas",
      "to_task": "verify_failover",
      "kind": "hard"
    }
  ]
}

